"""Title cards, end credits and lower thirds, generated by ffmpeg alone.

No image or font assets ship with the project: the background is a lavfi
`color`/`gradients` source and text is drawn with `drawtext`, so a card is just
a few filter chains (a `FilterGraph`, shared with transitions.py) that the
caller splices into its own ``-filter_complex`` -- typically as an extra "clip"
that is joined to the montage with xfade.

Why textfile= everywhere
------------------------
Titles come from user config and player names, so they may contain
apostrophes, commas, colons, percent signs or non-ASCII.  Inline `text=` needs
several nested escaping levels (and an apostrophe inside quotes cannot be
escaped at all), whereas a UTF-8 file read via `textfile=` needs none.  We also
set `expansion=none` so `%{...}` or backslashes in a title are never
interpreted as drawtext directives.

Why one drawtext per line in credits
------------------------------------
`drawtext` only gained multi-line centring (`text_align`) in recent ffmpeg
versions.  Drawing each line separately at a computed y works on every build and
makes scroll maths exact (no dependence on `text_h`).
"""

from __future__ import annotations

import glob
import os
import re
import shutil
import subprocess
from dataclasses import dataclass
from pathlib import Path
from typing import Optional, Sequence

from .transitions import FilterGraph, _fmt, esc_expr

ANIMATIONS: tuple[str, ...] = ("none", "fade", "slide-up", "typewriter")

#: Common bold sans fonts across platforms, best first.  Bold reads better at
#: video resolution and every entry ships with its OS (or the usual distro
#: font packages).
FONT_CANDIDATES: tuple[str, ...] = (
    # Windows
    r"C:\Windows\Fonts\arialbd.ttf",
    r"C:\Windows\Fonts\segoeuib.ttf",
    r"C:\Windows\Fonts\arial.ttf",
    r"C:\Windows\Fonts\calibrib.ttf",
    # macOS
    "/System/Library/Fonts/Supplemental/Arial Bold.ttf",
    "/Library/Fonts/Arial Bold.ttf",
    "/System/Library/Fonts/Helvetica.ttc",
    "/System/Library/Fonts/Supplemental/Arial.ttf",
    # Linux
    "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
    "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
    "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf",
    "/usr/share/fonts/truetype/freefont/FreeSansBold.ttf",
    "/usr/share/fonts/truetype/noto/NotoSans-Bold.ttf",
    "/usr/share/fonts/dejavu/DejaVuSans-Bold.ttf",
    "/usr/share/fonts/TTF/DejaVuSans-Bold.ttf",
    "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
)

#: Last-resort search roots when no named candidate exists.
_FONT_DIRS: tuple[str, ...] = (
    "/usr/share/fonts", "/usr/local/share/fonts",
    "/System/Library/Fonts", "/Library/Fonts", r"C:\Windows\Fonts",
)

FONT_ENV = "MCMONTAGE_FONT"

_COLOR_RE = re.compile(r"^[A-Za-z0-9#@._]+$")


class FontNotFoundError(RuntimeError):
    """No usable font file; drawtext cannot render text without one."""


def find_font(extra: Sequence[str] = ()) -> Optional[str]:
    """Return the path of a usable font file, or None if nothing is found.

    Order: $MCMONTAGE_FONT, caller-supplied `extra`, FONT_CANDIDATES, then any
    .ttf/.otf under the usual font directories.  Returning None (rather than
    guessing a path) lets callers choose between an error and a text-less card;
    ffmpeg's own failure for a bad fontfile is an opaque "Cannot find a valid
    font".
    """
    env = os.environ.get(FONT_ENV)
    for cand in ([env] if env else []) + list(extra) + list(FONT_CANDIDATES):
        if cand and Path(cand).is_file():
            return str(cand)
    for root in _FONT_DIRS:
        for ext in ("ttf", "otf"):
            hits = sorted(glob.glob(os.path.join(root, "**", f"*.{ext}"),
                                    recursive=True))
            # prefer sans families so a symbol/emoji font is not picked
            hits.sort(key=lambda p: ("sans" not in p.lower(), p))
            if hits:
                return hits[0]
    return None


_filters_cache: dict[str, str] = {}


def _filter_list(ffmpeg: str) -> str:
    if ffmpeg not in _filters_cache:
        out = ""
        if shutil.which(ffmpeg):
            try:
                out = subprocess.run([ffmpeg, "-hide_banner", "-filters"],
                                     capture_output=True, text=True,
                                     timeout=20).stdout
            except (OSError, subprocess.SubprocessError):
                out = ""
        _filters_cache[ffmpeg] = out
    return _filters_cache[ffmpeg]


def has_filter(name: str, ffmpeg: str = "ffmpeg") -> bool:
    """True if `ffmpeg -filters` lists `name`."""
    return bool(re.search(rf"^\s*\S+\s+{re.escape(name)}\s", _filter_list(ffmpeg),
                          re.M))


def drawtext_available(ffmpeg: str = "ffmpeg") -> bool:
    """drawtext needs ffmpeg built with --enable-libfreetype; many slim builds
    lack it, so check rather than fail mid-render."""
    return has_filter("drawtext", ffmpeg)


def esc_path(p: str) -> str:
    """Escape a filesystem path for a single-quoted filter option value."""
    return str(p).replace("\\", "/").replace(":", r"\:")


def _check_color(c: str, what: str) -> str:
    if not _COLOR_RE.match(c):
        raise ValueError(f"invalid {what} colour {c!r}")
    return c


@dataclass(frozen=True)
class CardStyle:
    """Look and motion of a card.

    bg_color / bg_color2 -- solid colour, or a gradient when bg_color2 is set
    gradient             -- "vertical" | "horizontal" | "diagonal"
    font                 -- font file; None means find_font()
    animation            -- one of ANIMATIONS
    fade_in / fade_out   -- seconds (clamped to half the card so they never
                            overlap)
    on_missing_font      -- "error" raises FontNotFoundError; "blank" renders
                            the background without text
    """

    bg_color: str = "0x101820"
    bg_color2: Optional[str] = None
    gradient: str = "vertical"
    font: Optional[str] = None
    font_color: str = "white"
    subtitle_color: str = "white@0.85"
    title_size: float = 0.075       # fraction of frame height
    subtitle_size: float = 0.035
    credits_size: float = 0.04
    animation: str = "fade"
    fade_in: float = 0.5
    fade_out: float = 0.5
    shadow: bool = True
    on_missing_font: str = "error"
    lt_box_color: str = "black@0.55"

    def __post_init__(self) -> None:
        if self.animation not in ANIMATIONS:
            raise ValueError(
                f"unknown animation {self.animation!r}; expected {ANIMATIONS}")
        if self.gradient not in ("vertical", "horizontal", "diagonal"):
            raise ValueError(f"unknown gradient direction {self.gradient!r}")
        if self.on_missing_font not in ("error", "blank"):
            raise ValueError("on_missing_font must be 'error' or 'blank'")
        if self.fade_in < 0 or self.fade_out < 0:
            raise ValueError("fades must be >= 0")
        for c, w in ((self.bg_color, "background"), (self.font_color, "font"),
                     (self.subtitle_color, "subtitle"),
                     (self.lt_box_color, "box")):
            _check_color(c, w)
        if self.bg_color2 is not None:
            _check_color(self.bg_color2, "background")


def _resolve_font(style: CardStyle) -> Optional[str]:
    """Font path for `style`, honouring on_missing_font."""
    if style.font:
        if not Path(style.font).is_file():
            if style.on_missing_font == "blank":
                return None
            raise FontNotFoundError(f"font file not found: {style.font}")
        return style.font
    font = find_font()
    if font is None and style.on_missing_font == "error":
        raise FontNotFoundError(
            "no usable font found; set CardStyle.font, set "
            f"${FONT_ENV}, or install one (e.g. DejaVu Sans)")
    return font


def _validate_dims(duration: float, width: int, height: int, fps: float) -> None:
    if not duration > 0:
        raise ValueError("duration must be > 0")
    if width <= 0 or height <= 0 or fps <= 0:
        raise ValueError("width, height and fps must be positive")


def _fmt_fps(f: float) -> str:
    return str(int(f)) if float(f).is_integer() else _fmt(f)


def background_chain(label: str, width: int, height: int, fps: float,
                     duration: float, style: CardStyle) -> str:
    """Source chain producing the card background as `[label]`."""
    base = f"s={width}x{height}:r={_fmt_fps(fps)}:d={_fmt(duration)}"
    if style.bg_color2 is None:
        return f"color=c={style.bg_color}:{base}[{label}]"
    x1, y1 = {"vertical": (0, height), "horizontal": (width, 0),
              "diagonal": (width, height)}[style.gradient]
    # speed has a minimum of 1e-5 in ffmpeg; that is effectively a still image
    return (f"gradients={base}:c0={style.bg_color}:c1={style.bg_color2}"
            f":x0=0:y0=0:x1={x1}:y1={y1}:speed=0.00001:seed=1[{label}]")


def fit_font_size(lines: Sequence[str], size: int, width: int,
                  max_frac: float = 0.9) -> int:
    """Shrink `size` so the longest line fits `max_frac` of the frame width.

    Assumes ~0.62 em average advance for bold sans, which errs on the safe
    side for Latin text; there is no portable way to measure text before
    rendering.
    """
    longest = max((len(ln) for ln in lines), default=1) or 1
    need = longest * size * 0.62
    if need <= width * max_frac:
        return size
    return max(12, int(width * max_frac / (longest * 0.62)))


def _write_text(path: Path, text: str) -> str:
    """Write text as UTF-8 with LF newlines and return the escaped path."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(text.replace("\r\n", "\n").replace("\r", "\n")
                     .encode("utf-8"))
    return esc_path(str(path))


def _drawtext(font: str, textfile: str, size: int, color: str, x: str, y: str,
              *, alpha: Optional[str] = None, shadow: int = 0,
              enable: Optional[tuple[float, float]] = None,
              box: Optional[str] = None, boxborder: int = 0) -> str:
    """One drawtext filter reading its text from an escaped textfile path."""
    s = (f"drawtext=fontfile='{esc_path(font)}':textfile='{textfile}'"
         f":expansion=none:fontcolor={color}:fontsize={size}"
         f":x={esc_expr(x)}:y={esc_expr(y)}")
    if shadow:
        s += f":shadowcolor=black@0.6:shadowx={shadow}:shadowy={shadow}"
    if box:
        s += f":box=1:boxcolor={box}:boxborderw={boxborder}"
    if alpha:
        s += f":alpha={esc_expr(alpha)}"
    if enable:
        s += f":enable='between(t,{_fmt(enable[0])},{_fmt(enable[1])})'"
    return s


def fade_alpha(duration: float, fade_in: float, fade_out: float,
               delay: float = 0.0) -> str:
    """Alpha expression: ramp in after `delay`, hold, ramp out at the end."""
    parts = []
    if fade_in > 0:
        parts.append(f"max(0,min(1,(t-{_fmt(delay)})/{_fmt(fade_in)}))")
    elif delay > 0:
        parts.append(f"gte(t,{_fmt(delay)})")
    if fade_out > 0:
        parts.append(f"max(0,min(1,({_fmt(duration)}-t)/{_fmt(fade_out)}))")
    return "*".join(parts) if parts else "1"


def _clamped_fades(duration: float, style: CardStyle) -> tuple[float, float]:
    half = duration / 2
    return min(style.fade_in, half), min(style.fade_out, half)


def build_card_graph(title: str, subtitle: Optional[str] = None,
                     duration: float = 3.0, width: int = 1920,
                     height: int = 1080, fps: float = 30,
                     style: Optional[CardStyle] = None,
                     work_dir=None, prefix: str = "card") -> FilterGraph:
    """Title card: background + title (+ subtitle) with an entrance animation.

    The chains contain their own lavfi source, so the graph needs no ffmpeg
    input.  The result is yuv420p / SAR 1 / `fps`, ready for xfade.  `prefix`
    namespaces both labels and text files so several cards can coexist.
    """
    style = style or CardStyle()
    _validate_dims(duration, width, height, fps)
    if not title or not title.strip():
        raise ValueError("title must not be empty")
    if work_dir is None:
        raise ValueError("work_dir is required (text files are written there)")
    work_dir = Path(work_dir)
    font = _resolve_font(style)
    bg = f"{prefix}bg"
    out = f"{prefix}out"
    chains = [background_chain(bg, width, height, fps, duration, style)]
    finish = "format=yuv420p,setsar=1"

    if font is None:     # on_missing_font == "blank"
        chains.append(f"[{bg}]{finish}[{out}]")
        return FilterGraph(tuple(chains), out, float(duration))

    fi, fo = _clamped_fades(duration, style)
    size_main = fit_font_size(title.split("\n"), max(28, int(height * style.title_size)), width)
    size_sub = max(18, int(height * style.subtitle_size))
    if subtitle:
        size_sub = fit_font_size(subtitle.split("\n"), size_sub, width)
    t_file = _write_text(work_dir / f"{prefix}_title.txt", title)
    s_file = (_write_text(work_dir / f"{prefix}_subtitle.txt", subtitle)
              if subtitle else None)
    sh_main, sh_sub = (3, 2) if style.shadow else (0, 0)
    shift = int(height * 0.03) if subtitle else 0
    y_title = f"(h-text_h)/2-{shift}"
    # subtitle sits just below the title's descenders, whatever the font size
    y_sub = f"(h-text_h)/2{int(size_main * 0.6 + size_sub * 0.9) - shift:+d}"
    x_c = "(w-text_w)/2"
    slide = int(height * 0.06)
    anim = style.animation

    def sliding(y: str, delay: float) -> str:
        # ease-out quadratic: fast at first, settling into place
        prog = f"max(0,min(1,(t-{_fmt(delay)})/{_fmt(max(fi, 0.01))}))"
        return f"{y}+{slide}*pow(1-{prog},2)"

    sub_delay = 0.0 if anim in ("none",) else min(0.25, duration / 4)
    sub_alpha = None if anim == "none" else fade_alpha(duration, fi, fo, sub_delay)

    if anim == "typewriter":
        # A left-to-right wipe mask over the title: text is drawn white-on-black
        # as a gray layer, multiplied by a sliding white slab (overlay x is
        # evaluated per frame, whereas drawbox's w is not), then used as the
        # alpha of a flat colour layer.  This avoids one drawtext per character
        # (impossible to centre without knowing glyph widths).
        reveal = min(max(0.4, len(title) / 18), duration * 0.6)
        start = min(0.2, duration / 10)
        a, b = 0.12, 0.88          # span of the frame the wipe sweeps
        # right edge of the white slab, minus its width, is the overlay x
        xexpr = (f"{int(width * a)}-{width}+{int(width * (b - a))}"
                 f"*max(0,min(1,(t-{_fmt(start)})/{_fmt(reveal)}))")
        base = f"s={width}x{height}:r={_fmt_fps(fps)}:d={_fmt(duration)}"
        # lavfi black is 16, not 0, in limited range; alphamerge reads the raw
        # byte as alpha, which would tint the whole frame by ~6%
        full = "lutyuv=y=" + esc_expr("clip((val-16)*255/219,0,255)")
        dt = _drawtext(font, t_file, size_main, "white", x_c, y_title)
        fade_out = (f",fade=t=out:st={_fmt(duration - fo)}:d={_fmt(fo)}"
                    if fo > 0 else "")
        chains += [
            f"color=c=black:{base},{dt},format=gray,{full}[{prefix}tg]",
            f"color=c=black:{base}[{prefix}mb]",
            f"color=c=white:{base}[{prefix}mw]",
            f"[{prefix}mb][{prefix}mw]overlay=x={esc_expr(xexpr)}:y=0"
            f",format=gray,{full}[{prefix}mk]",
            f"[{prefix}tg][{prefix}mk]blend=all_mode=multiply,format=gray"
            f"{fade_out}[{prefix}al]",
            f"color=c={style.font_color}:{base},format=yuv420p[{prefix}col]",
            f"[{prefix}col][{prefix}al]alphamerge[{prefix}txt]",
        ]
        tail = ["overlay=format=auto"]
        if s_file:
            tail.append(_drawtext(font, s_file, size_sub, style.subtitle_color,
                                  x_c, y_sub, alpha=fade_alpha(
                                      duration, fi, fo, start + reveal),
                                  shadow=sh_sub))
        chains.append(f"[{bg}][{prefix}txt]" + ",".join(tail + [finish])
                      + f"[{out}]")
        return FilterGraph(tuple(chains), out, float(duration))

    title_alpha = None if anim == "none" else fade_alpha(duration, fi, fo)
    y_t = sliding(y_title, 0.0) if anim == "slide-up" else y_title
    filters = [_drawtext(font, t_file, size_main, style.font_color, x_c, y_t,
                         alpha=title_alpha, shadow=sh_main)]
    if s_file:
        y_s = sliding(y_sub, sub_delay) if anim == "slide-up" else y_sub
        filters.append(_drawtext(font, s_file, size_sub, style.subtitle_color,
                                 x_c, y_s, alpha=sub_alpha, shadow=sh_sub))
    chains.append(f"[{bg}]" + ",".join(filters + [finish]) + f"[{out}]")
    return FilterGraph(tuple(chains), out, float(duration))


def credits_card(lines: Sequence[str], duration: float = 8.0,
                 width: int = 1920, height: int = 1080, fps: float = 30,
                 style: Optional[CardStyle] = None, work_dir=None,
                 mode: str = "stack", heading: Optional[str] = "Music",
                 prefix: str = "credits") -> FilterGraph:
    """End-credits card, e.g. music attributions.

    mode "stack"  -- all lines centred on screen, fading in and out
    mode "scroll" -- the block rises from below the frame to above it over the
                     whole duration (classic film credits)

    `heading` becomes a larger first line.  Blank strings in `lines` leave a
    gap.  Lines are not wrapped; very long ones shrink the font to fit.
    """
    style = style or CardStyle()
    _validate_dims(duration, width, height, fps)
    if mode not in ("stack", "scroll"):
        raise ValueError("mode must be 'stack' or 'scroll'")
    body = [str(ln) for ln in lines]
    if not any(ln.strip() for ln in body) and not heading:
        raise ValueError("credits need at least one non-empty line")
    if work_dir is None:
        raise ValueError("work_dir is required (text files are written there)")
    work_dir = Path(work_dir)
    font = _resolve_font(style)
    bg, out = f"{prefix}bg", f"{prefix}out"
    chains = [background_chain(bg, width, height, fps, duration, style)]
    finish = "format=yuv420p,setsar=1"
    if font is None:
        chains.append(f"[{bg}]{finish}[{out}]")
        return FilterGraph(tuple(chains), out, float(duration))

    size = max(16, int(height * style.credits_size))
    size = fit_font_size(body + ([heading] if heading else []), size, width)
    head_size = int(size * 1.35)
    line_h = int(size * 1.6)
    rows: list[tuple[str, int]] = []      # (text, font size), "" = gap
    if heading:
        rows += [(heading, head_size), ("", size)]
    rows += [(ln, size) for ln in body]
    block_h = line_h * len(rows)
    fi, fo = _clamped_fades(duration, style)
    shadow = 2 if style.shadow else 0

    filters = []
    for i, (text, sz) in enumerate(rows):
        if not text.strip():
            continue
        tf = _write_text(work_dir / f"{prefix}_line{i}.txt", text)
        offset = i * line_h
        if mode == "stack":
            y = f"{(height - block_h) // 2 + offset}"
            alpha = fade_alpha(duration, fi, fo)
        else:
            # starts fully below the frame, ends fully above it
            y = (f"{height}-({height}+{block_h})*t/{_fmt(duration)}+{offset}")
            alpha = None
        color = style.font_color if (heading and i == 0) else style.subtitle_color
        filters.append(_drawtext(font, tf, sz, color, "(w-text_w)/2", y,
                                 alpha=alpha, shadow=shadow))
    if not filters:
        raise ValueError("credits need at least one non-empty line")
    chains.append(f"[{bg}]" + ",".join(filters + [finish]) + f"[{out}]")
    return FilterGraph(tuple(chains), out, float(duration))


def lower_third(text: str, start: float, end: float, *, width: int,
                height: int, work_dir, subtitle: Optional[str] = None,
                in_label: str = "vout", out_label: Optional[str] = None,
                style: Optional[CardStyle] = None, prefix: str = "lt",
                position: str = "bottom-left", slide: float = 0.3
                ) -> FilterGraph:
    """Overlay a label (e.g. "Kill: Zombie") on an existing stream.

    The chain reads `[in_label]` and writes `[out_label]`; text appears only
    inside enable='between(t,start,end)' and slides in from the left over
    `slide` seconds.  Each text gets a tight semi-transparent box, which keeps
    it legible on any footage without needing to know the text width.  The
    returned graph's `duration` is `end`: the stream's own length is unchanged,
    so render it with render_graph_args(..., trim_to_duration=False) or the
    output would be cut at `end`.
    Give concurrent lower thirds distinct prefix / labels (text files are named
    after `prefix`).
    """
    style = style or CardStyle()
    if not text or not text.strip():
        raise ValueError("lower third text must not be empty")
    if not (end > start >= 0):
        raise ValueError(f"need 0 <= start < end, got {start!r}..{end!r}")
    if width <= 0 or height <= 0:
        raise ValueError("width and height must be positive")
    if position not in ("bottom-left", "bottom-center"):
        raise ValueError("position must be 'bottom-left' or 'bottom-center'")
    if work_dir is None:
        raise ValueError("work_dir is required (text files are written there)")
    work_dir = Path(work_dir)
    out_label = out_label or f"{prefix}out"
    font = _resolve_font(style)
    if font is None:
        # nothing to draw; pass the stream through untouched
        return FilterGraph((f"[{in_label}]null[{out_label}]",), out_label,
                           float(end))

    size = fit_font_size(text.split("\n"), max(20, int(height * 0.045)), width,
                         max_frac=0.8)
    size_sub = max(14, int(size * 0.65))
    pad = max(6, size // 3)
    x0 = f"{int(width * 0.05)}" if position == "bottom-left" else "(w-text_w)/2"
    dist = int(width * 0.04)
    slide_t = max(slide, 0.01)
    if position == "bottom-left":
        x = (f"{x0}-{dist}*pow(max(0,1-(t-{_fmt(start)})/{_fmt(slide_t)}),2)")
    else:
        x = x0
    y_main = int(height * (0.80 if subtitle else 0.84))
    t_file = _write_text(work_dir / f"{prefix}_text.txt", text)
    filters = [_drawtext(font, t_file, size, style.font_color, x, str(y_main),
                         enable=(start, end), box=style.lt_box_color,
                         boxborder=pad)]
    if subtitle:
        s_file = _write_text(work_dir / f"{prefix}_subtext.txt", subtitle)
        y_sub = min(y_main + size + 2 * pad + 4, height - size_sub - 2 * pad)
        filters.append(_drawtext(font, s_file, size_sub, style.subtitle_color,
                                 x, str(y_sub), enable=(start, end),
                                 box=style.lt_box_color, boxborder=pad))
    chain = f"[{in_label}]" + ",".join(filters) + f"[{out_label}]"
    return FilterGraph((chain,), out_label, float(end))


__all__ = [
    "ANIMATIONS", "CardStyle", "FONT_CANDIDATES", "FontNotFoundError",
    "build_card_graph", "credits_card", "drawtext_available", "esc_path",
    "fade_alpha", "find_font", "fit_font_size", "has_filter", "lower_third",
]
